use serde_json::{json,Value};
use std::{collections::BTreeMap,fs,path::Path};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn median(mut x:Vec<f64>)->f64{assert!(!x.is_empty()&&x.iter().all(|n|n.is_finite()));x.sort_by(f64::total_cmp);let m=x.len()/2;if x.len()%2==0{(x[m-1]+x[m])/2.}else{x[m]}}
fn geo(x:&[f64])->f64{assert!(!x.is_empty()&&x.iter().all(|n|n.is_finite()&&*n>0.));(x.iter().map(|n|n.ln()).sum::<f64>()/x.len()as f64).exp()}
fn number(v:&Value,k:&str)->f64{v[k].as_f64().unwrap()}
fn main(){let args=std::env::args().skip(1).collect::<Vec<_>>();assert_eq!(args.len(),2);let root=Path::new(&args[0]);let config=read(root.join("perf-plan.json"));let report=read(root.join("perf/result.json"));assert_eq!(report["status"],"complete");assert_eq!(report["distinct_verified_exports"],219);assert_eq!(config["blocks"],7);assert_eq!(config["monotonic_clock"],true);let raw=read(root.join("perf/rows.json"));let rows=raw.as_array().unwrap();assert_eq!(rows.len(),219);let latency=rows.iter().filter(|r|r["phase"]=="latency").collect::<Vec<_>>();assert_eq!(latency.len(),210);let profiles=rows.iter().filter(|r|r["phase"]=="profile").collect::<Vec<_>>();assert_eq!(profiles.len(),9);let sdk=rows.iter().map(|r|r["samples_ms"].as_array().unwrap().len()+3).sum::<usize>();assert_eq!(sdk,9120);assert!(profiles.iter().all(|r|r["profile"]["lost_records"]==0&&r["profile"]["sampled_pids"].as_array().unwrap().len()==1));let cases=config["cases"].as_array().unwrap();assert_eq!(cases.len(),10);let lookup=|name:&str,variant:&str,block:usize|{let hits=latency.iter().filter(|r|r["case"]==name&&r["variant"]==variant&&r["block"]==block).collect::<Vec<_>>();assert_eq!(hits.len(),1);*hits[0]};let ratios=|name:&str,variant:&str,control:&str|(0..7).map(|b|number(lookup(name,variant,b),"median_ms")/number(lookup(name,control,b),"median_ms")).collect::<Vec<_>>();let mut failed=Vec::new();let mut summaries=BTreeMap::new();let mut references=Vec::new();for case in cases{let name=case["name"].as_str().unwrap();let rounds=case["rounds"].as_u64().unwrap();assert_eq!(rounds,if name=="1x2-w16"{101}else{31});let mut metrics=BTreeMap::new();for variant in ["accepted","off","on"]{let picked=(0..7).map(|b|lookup(name,variant,b)).collect::<Vec<_>>();for r in &picked{assert_eq!(r["samples_ms"].as_array().unwrap().len(),rounds as usize);assert_eq!(r["summary"]["rounds"],rounds);assert_eq!(r["summary"]["workers"],case["workers"]);assert_eq!(r["summary"]["priming"],3);}metrics.insert(variant,json!({"median_ms":median(picked.iter().map(|r|number(r,"median_ms")).collect()),"cpu_ms_per_request":median(picked.iter().map(|r|(number(&r["summary"],"user_cpu_ms")+number(&r["summary"],"system_cpu_ms"))/rounds as f64).collect()),"maxrss_mib":picked.iter().map(|r|number(&r["summary"],"whole_process_maxrss_kib")/1024.).max_by(f64::total_cmp).unwrap(),"voluntary_switches_per_request":median(picked.iter().map(|r|number(&r["summary"],"voluntary_switches")/rounds as f64).collect())}));}let cal=median(ratios(name,"off","accepted"));let factor=cal.max(1./cal);if factor>1.03{failed.push(format!("{name}: OFF calibration factor {factor}"));}let mut comparisons=BTreeMap::new();for control in ["accepted","off"]{let paired=ratios(name,"on",control);let ratio=median(paired.clone());let wins=paired.iter().filter(|r|**r<1.).count();if ratio>1.02{failed.push(format!("{name}/{control}: nonregression ratio {ratio}"));}for(b,r)in paired.iter().enumerate(){if *r>1.05{failed.push(format!("{name}/{control}/block{b}: ratio{r}"));}}if name=="1x2-w32"&&(ratio>=1.||wins<4){failed.push(format!("{name}/{control}: primary ratio{ratio},wins{wins}/7"));}comparisons.insert(control,json!({"paired_median":ratio,"wins":wins,"paired_ratios":paired}));}if case["workers"]==32&&!case["reference"].is_null(){let ms=number(&metrics["on"],"median_ms");let cpu=number(&case["reference"],"cpu_ms");let metal=number(&case["reference"],"metal_ms");references.push(json!({"shape":case["shape"],"cpu_reference_ms":cpu,"metal_reference_ms":metal,"accepted_ms":metrics["accepted"]["median_ms"],"off_ms":metrics["off"]["median_ms"],"on_ms":ms,"on_cpu_speedup":cpu/ms,"on_metal_speedup":metal/ms,"on_observed_cpu10x":cpu/ms>=10.}));}summaries.insert(name,json!({"metrics":metrics,"on_over_control":comparisons,"off_calibration_factor":factor}));}
assert_eq!(references.len(),8);let original=cases.iter().filter(|c|c["workers"]==32&&!c["reference"].is_null()).collect::<Vec<_>>();assert_eq!(original.len(),8);let mut aggregate=BTreeMap::new();for control in ["accepted","off"]{let paired=(0..7).map(|b|geo(&original.iter().map(|c|{let n=c["name"].as_str().unwrap();number(lookup(n,"on",b),"median_ms")/number(lookup(n,control,b),"median_ms")}).collect::<Vec<_>>())).collect::<Vec<_>>();let ratio=median(paired.clone());if ratio>=1.{failed.push(format!("original8/{control}: paired geometric ratio {ratio}"));}aggregate.insert(control,json!({"paired_median":ratio,"block_geomeans":paired}));}let samples=profiles.iter().map(|r|r["profile"]["samples"].as_u64().unwrap()).sum::<u64>();let result=json!({"status":if failed.is_empty(){"all-nine local speed screen passed; further qualification required"}else{"all-nine local speed screen failed"},"performance_gate_passed":failed.is_empty(),"failed_checks":failed,"cases":summaries,"original8_aggregate":aggregate,"m5_supplied_references":references,"sdk_perf":sdk,"profiles":9,"profile_samples":samples,"lost_records":0,"distinct_perf_exports":219,"adopted":false,"goal_achieved":false,"scope":"Complete local SDK measurements, all nine shapes32workers plus physical16primary101rounds. Source,correctness and speed observations do not establish portable/concurrent SDK/pressure/large/target-host qualification. Historical M5 references, not fresh M5 timing. All8goal remains subject to clean qualification."});fs::write(&args[1],format!("{}\n",serde_json::to_string_pretty(&result).unwrap())).unwrap();println!("{}",result["status"]);}
#[cfg(test)]mod tests{use super::*;#[test]fn median_and_positive_geometric_ratios_keep_every_block(){assert_eq!(median(vec![7.,1.,6.,2.,5.,3.,4.]),4.);assert_eq!(median(vec![2.,4.]),3.);assert!((geo(&[0.5,2.,1.,1.,1.,1.,1.,1.])-1.).abs()<1e-14);assert!(std::panic::catch_unwind(||geo(&[0.])).is_err());assert!(std::panic::catch_unwind(||median(vec![f64::NAN])).is_err());}}
